 *
 * ?뚯뼱???덈꺼???롮쓽 寃쎄퀎?멸??띾뒗 ?뚯꽌媛 ?뺥븯吏 ?딆쑝誘濡?FL쨌GL쨌?븀쨴訝뗧ク쨌RCL??
 * ?욎뿬 ?덈떎) ?ш린???ъ슜?먯쓽 ?좏깮??諛쏅뒗?? ?롮쓽 ?대쫫??吏?대궡吏 ?딄퀬 洹??롮쓽
 * **諛붾떏???섎뒗 ?덈꺼???먮Ц**??洹몃?濡??대떎 ??媛숈? ?믪씠???쇰꺼???섏씠硫?????
 * ?④릿???ㅻЪ???뚥릎鸚?짘1FL?띻낵 ?뚦읃繹뺾L?띿씠 洹몃젃??.
 */
export function applyElevation(
  project: Project,
  {
    candidate,
    topLevelIndex,
    bottomLevelIndex,
    discardMembers = false,
  }: ElevationApplyOptions,
): ElevationApplyResult {
  const valid =
    Number.isInteger(topLevelIndex) &&
    Number.isInteger(bottomLevelIndex) &&
    topLevelIndex >= 0 &&
    bottomLevelIndex > topLevelIndex &&
    bottomLevelIndex < candidate.levels.length
  if (!valid) {
    return { project, applied: 0, refusal: '?롧칱?꿜툖閭? }
  }

  // ?롫? 媛덈㈃ 遺?ъ쓽 storyId媛 媛由ы궎???롪? ?щ씪吏꾨떎. 遺遺?諛섏쁺?쇰줈 ?섏뼱媛硫?
  // ?뚰?由?梨꾨줈 ?꾩꽦??寃껁띿씠 ?섎?濡??듭㎏濡?嫄곕??섍퀬, ?ъ슜?먭? ?뺥븳??
  if (project.members.length > 0 && !discardMembers) {
    return { project, applied: 0, refusal: '?ⓩ쓲?귙굤?롧쉰?쎽툖?? }
  }

  const stories: Story[] = []
  // ?꾨㈃? ?꾩뿉???꾨옒, `Project.stories`???꾨옒?먯꽌 ?꾨떎 (columnEnds媛
  // stories[level - 1]???뚯븘???롢띾줈 ?쎈뒗??
  for (let i = bottomLevelIndex - 1; i >= topLevelIndex; i--) {
    const floor = candidate.levels[i + 1]
    const name =
      floor.labels.length > 0
        ? floor.labels.join('竊?)
        : `${bottomLevelIndex - i}`
    stories.push({
      id: `story-${bottomLevelIndex - i}`,
      name,
      height: candidate.heightsMm[i],
    })
  }

  return {
    project: { ...project, stories, members: [] },
    applied: stories.length,
  }
}
